}

// exec deletes the rows, with their join table rows, in one transaction, and
// returns how many there were.
pub fn (b TagDelete) exec() !int {
	return b.graph.client.delete(b.data)
}

// tags_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) tags_by_keys(keys []string) ![]TagNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.tags().where(load.in_keys('id', keys, .int)).all()!
	mut by_key := map[string]TagNode{}
	for row in rows {
		by_key[row.tag.id.str()] = row
	}
	mut found := []TagNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'tags'
			}
		}
	}
	return found
}

// CreateTagInput is what a create of a `tags` row sets, as the GraphQL input
// `CreateTagInput` gives it: `none` and empty lists leave things as
// they are.
pub struct CreateTagInput {
pub mut:
	name        ?string
	article_ids []i64
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b TagCreate) set_input(input CreateTagInput) TagCreate {
	mut next := b
	if v := input.name {
		next = next.set_name(v)
	}
	if input.article_ids.len > 0 {
		next = next.add_articles_ids(...input.article_ids)
	}
	return next
}

// UpdateTagInput is what a update of a `tags` row sets, as the GraphQL input
// `UpdateTagInput` gives it: `none` and empty lists leave things as
// they are.
pub struct UpdateTagInput {
pub mut:
	name               ?string
	add_article_ids    []i64
	remove_article_ids []i64
	clear_articles     bool
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b TagUpdateOne) set_input(input UpdateTagInput) TagUpdateOne {
	mut next := b
	if input.clear_articles {
		next = next.clear_articles()
	}
	if v := input.name {
		next = next.set_name(v)
	}
	if input.add_article_ids.len > 0 {
		next = next.add_articles_ids(...input.add_article_ids)
	}
	if input.remove_article_ids.len > 0 {
		next = next.remove_articles_ids(...input.remove_article_ids)
	}
	return next
}
